mapper.select:
SELECT bs.billing_session_id, bs.request_id, bs.employee_id, bs.token_id, bs.channel_id, bs.model_id, bs.endpoint_type, bs.preconsume_quota, bs.settled_quota, bs.delta_quota, bs.billing_state, bs.upstream_status_code, bs.gateway_status_code, bs.latency_ms, bs.error_msg, bs.settled_time, bs.update_time, bs.create_time, m.model_name, c.channel_name FROM t_ai_billing_session bs LEFT JOIN t_ai_model m ON bs.model_id = m.model_id LEFT JOIN t_ai_channel c ON bs.channel_id = c.channel_id
AND bs.employee_id = #{queryForm.employeeId}
AND bs.request_id = #{queryForm.requestId}
AND bs.billing_state = #{queryForm.billingState}
AND bs.create_time >= #{queryForm.startTime}
AND bs.create_time <= #{queryForm.endTime}
ORDER BY bs.create_time DESC
